namespace BareWin;
public record Tweak(string Pt, string En, string Comando, bool Padrao = true) { public string Titulo => L.En ? En : Pt; }
public static class Debloat {
  const string Reg = "function Set-BwReg($p,$n,$v){ if(!(Test-Path $p)){New-Item $p -Force|Out-Null}; New-ItemProperty $p $n -Value $v -PropertyType DWord -Force|Out-Null; Write-Output \"$p\\$n=$v\" }\n";
  public static readonly Tweak[] Itens = {
    new("Remover apps pré-instalados (Xbox, Clipchamp, Notícias, Dicas)", "Remove preinstalled apps (Xbox, Clipchamp, News, Tips)",
      "foreach($n in '*Xbox*','*Clipchamp*','*BingNews*','*GetHelp*','*Getstarted*'){ Get-AppxPackage -Name $n | ? { -not $_.NonRemovable -and -not $_.IsFramework -and $_.SignatureKind -ne 'System' -and $_.InstallLocation -notlike '*\\SystemApps\\*' } | % { Write-Output \"Removendo $($_.Name)\"; Remove-AppxPackage $_ -ErrorAction Continue } }; Write-Output 'Apps pré-instalados verificados.'"),
    new("Desativar telemetria", "Disable telemetry", Reg + "Set-BwReg 'HKLM:\\SOFTWARE\\Policies\\Microsoft\\Windows\\DataCollection' AllowTelemetry 0"),
    new("Desativar sugestões no Iniciar", "Disable Start menu suggestions", Reg + "Set-BwReg 'HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\ContentDeliveryManager' SystemPaneSuggestionsEnabled 0"),
    new("Desativar Cortana/Bing na pesquisa", "Disable Cortana/Bing in search", Reg + "Set-BwReg 'HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\Search' BingSearchEnabled 0\nSet-BwReg 'HKLM:\\SOFTWARE\\Policies\\Microsoft\\Windows\\Windows Search' AllowCortana 0"),
    new("Desativar Copilot (política + botão da barra)", "Disable Copilot (policy + taskbar button)", Reg +
      "Set-BwReg 'HKCU:\\Software\\Policies\\Microsoft\\Windows\\WindowsCopilot' TurnOffWindowsCopilot 1\nSet-BwReg 'HKLM:\\SOFTWARE\\Policies\\Microsoft\\Windows\\WindowsCopilot' TurnOffWindowsCopilot 1\nSet-BwReg 'HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Advanced' ShowCopilotButton 0\nSet-BwReg 'HKLM:\\SOFTWARE\\Policies\\Microsoft\\Edge' HubsSidebarEnabled 0"),
    new("Remover app Copilot (Appx)", "Remove Copilot app (Appx)",
      "Get-AppxPackage -AllUsers *Copilot* | ? { -not $_.NonRemovable -and $_.SignatureKind -ne 'System' -and $_.InstallLocation -notlike '*\\SystemApps\\*' } | % { Write-Output \"Removendo $($_.Name)\"; Remove-AppxPackage $_ -AllUsers -ErrorAction Continue }\nGet-AppxProvisionedPackage -Online | ? DisplayName -like '*Copilot*' | % { Remove-AppxProvisionedPackage -Online -PackageName $_.PackageName | Out-Null; Write-Output \"Desprovisionado $($_.DisplayName)\" }"),
    new("Desativar Edge em segundo plano / Startup Boost / first-run", "Disable Edge background / Startup Boost / first-run", Reg +
      "$e='HKLM:\\SOFTWARE\\Policies\\Microsoft\\Edge'\nSet-BwReg $e StartupBoostEnabled 0\nSet-BwReg $e BackgroundModeEnabled 0\nSet-BwReg $e HideFirstRunExperience 1\nSet-BwReg $e ShowRecommendationsEnabled 0\nSet-BwReg $e EdgeShoppingAssistantEnabled 0"),
    new("Desativar animações do Windows", "Disable Windows animations", Reg + "Set-BwReg 'HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Advanced' TaskbarAnimations 0\nSet-BwReg 'HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\VisualEffects' VisualFXSetting 3\nNew-ItemProperty 'HKCU:\\Control Panel\\Desktop\\WindowMetrics' MinAnimate -Value '0' -PropertyType String -Force|Out-Null; Write-Output 'MinAnimate=0'\n$m=[byte[]](0x90,0x12,0x03,0x80,0x10,0x00,0x00,0x00); Set-ItemProperty 'HKCU:\\Control Panel\\Desktop' UserPreferencesMask $m -Type Binary; Write-Output 'UserPreferencesMask ajustado (efeito após logoff)'"),
    new("Desativar transparência do Windows", "Disable Windows transparency", Reg + "Set-BwReg 'HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize' EnableTransparency 0"),
    new("Desinstalar Microsoft Edge (mantém WebView2; pode ser bloqueado pelo Windows)", "Uninstall Microsoft Edge (keeps WebView2; Windows may block it)",
      "Get-Process msedge -ErrorAction SilentlyContinue | Stop-Process -Force\n$s = Get-ChildItem \"${env:ProgramFiles(x86)}\\Microsoft\\Edge\\Application\\*\\Installer\\setup.exe\" -ErrorAction SilentlyContinue | Select -First 1\nif(!$s){ Write-Output 'Edge não encontrado.'; return }\nWrite-Output \"Usando $($s.FullName)\"\n$p = Start-Process $s.FullName '--uninstall --system-level --force-uninstall --verbose-logging' -Wait -PassThru\nWrite-Output \"setup.exe exit $($p.ExitCode)\"\nif(Test-Path \"${env:ProgramFiles(x86)}\\Microsoft\\Edge\\Application\\msedge.exe\"){ Write-Output 'Edge ainda presente: o Windows bloqueou a remoção nesta região/edição. As políticas acima continuam valendo.' } else { Write-Output 'Edge removido.' }", false),
  };
  public static Task Aplicar(Tweak t) { Runner.Log($"== {t.Titulo}"); return Runner.Ps(t.Comando); }
  public static Task CriarPontoRestauracao() =>
    Runner.Ps("try { Enable-ComputerRestore -Drive \"$env:SystemDrive\\\" -ErrorAction Stop; Checkpoint-Computer -Description 'BareWin' -RestorePointType MODIFY_SETTINGS -ErrorAction Stop; Write-Output 'Ponto de restauração criado.' } catch { Write-Output \"AVISO: ponto de restauração não criado (Proteção do Sistema/VSS desativado?): $($_.Exception.Message)\" }");
}
